5	func TestSlugify(t *testing.T) {
6		t.Parallel()
7	
8		cases := []struct {
9			name  string
10			title string
11			want  string
12		}{
13			{"plain title", "Hello World", "hello-world"},
14			{"accents fold to ascii", "Crème Brûlée à la Café", "creme-brulee-a-la-cafe"},
15			{"punctuation runs collapse", "Go -- Fast!!! & Safe", "go-fast-safe"},
16			{"leading and trailing symbols trimmed", "  ...Why Slugs?!  ", "why-slugs"},
17			{"digits kept", "Top 10 Tips for 2026", "top-10-tips-for-2026"},
18		}
19		for _, tc := range cases {
20			t.Run(tc.name, func(t *testing.T) {
21				t.Parallel()
22				if got := Slugify(tc.title); got != tc.want {
23					t.Fatalf("Slugify(%q) = %q, want %q", tc.title, got, tc.want)
24				}
25			})
26		}
27	}
