package main

import (
	"fmt"
)

var asciiFold = map[rune]string{
	'à': "a", 'á': "a", 'â': "a", 'ä': "a", 'ã': "a", 'å': "a",
	'ç': "c",
	'è': "e", 'é': "e", 'ê': "e", 'ë': "e",
	'ì': "i", 'í': "i", 'î': "i", 'ï': "i",
	'ñ': "n",
	'ò': "o", 'ó': "o", 'ô': "o", 'ö': "o", 'õ': "o", 'ø': "o",
	'ù': "u", 'ú': "u", 'û': "u", 'ü': "u",
	'ý': "y", 'ÿ': "y",
	'ß': "ss", 'æ': "ae", 'œ': "oe",
}

import (
	"strings"
	"unicode"
)

func Slugify(title string) string {
	var out strings.Builder
	pendingHyphen := false

	for _, r := range strings.ToLower(title) {
		if folded, ok := asciiFold[r]; ok {
			if pendingHyphen && out.Len() > 0 {
				out.WriteByte('-')
			}
			out.WriteString(folded)
			pendingHyphen = false
			continue
		}
		if r < unicode.MaxASCII && (unicode.IsLetter(r) || unicode.IsDigit(r)) {
			if pendingHyphen && out.Len() > 0 {
				out.WriteByte('-')
			}
			out.WriteRune(r)
			pendingHyphen = false
			continue
		}
		pendingHyphen = true
	}

	return out.String()
}

func main() {
	result := Slugify("!!!")
	fmt.Printf("Slugify(\"!!!\") = %q (length: %d, empty: %v)\n", result, len(result), result == "")
}
EOF
go run /tmp/test_slug.go

