10	func TestParseFrontMatterDate(t *testing.T) {
11		t.Parallel()
12	
13		valid := []struct {
14			name string
15			raw  string
16			want time.Time
17		}{
18			{"rfc3339 with Z", "2026-03-14T09:30:00Z", time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)},
19			{"rfc3339 with offset", "2026-03-14T11:30:00+02:00", time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)},
20			{"date only", "2026-03-14", time.Date(2026, 3, 14, 0, 0, 0, 0, time.UTC)},
21			{"quoted value", `"2026-03-14T09:30:00Z"`, time.Date(2026, 3, 14, 9, 30, 0, 0, time.UTC)},
22		}
23		for _, tc := range valid {
24			t.Run(tc.name, func(t *testing.T) {
25				t.Parallel()
26				got, err := parseFrontMatterDate("posts/pi-day.md", tc.raw)
27				if err != nil {
28					t.Fatalf("unexpected error: %v", err)
29				}
30				if !got.Equal(tc.want) || got.Location() != time.UTC {
31					t.Fatalf("got %v, want %v in UTC", got, tc.want)
32				}
33			})
34		}
35	
36		t.Run("invalid names the file", func(t *testing.T) {
37			t.Parallel()
38			_, err := parseFrontMatterDate("posts/bad.md", "14 March 2026")
39			if err == nil || !strings.Contains(err.Error(), "invalid date in posts/bad.md") {
40				t.Fatalf("want an error naming the file, got %v", err)
41			}
42		})
43	}
44	
45	func TestPageDate(t *testing.T) {
46		t.Parallel()
47	
48		t.Run("missing date", func(t *testing.T) {
49			t.Parallel()
50			_, err := PageDate("posts/draft.md", map[string]string{"title": "Draft"})
51			if !errors.Is(err, ErrNoDate) {
52				t.Fatalf("want ErrNoDate, got %v", err)
53			}
54		})
55	}
