2	
3	import (
4		"fmt"
5		"strings"
6		"time"
7	)
8	
9	// dateLayouts are the accepted forms of the `date:` field, most specific first.
10	var dateLayouts = []string{
11		time.RFC3339,
12		"2006-01-02",
13	}
14	
15	// parseFrontMatterDate turns the raw `date:` value of a page's front matter into a timestamp.
16	// file is the page's path, used only in the error message.
17	func parseFrontMatterDate(file, raw string) (time.Time, error) {
18		value := strings.Trim(strings.TrimSpace(raw), `"'`)
19		if value == "" {
20			return time.Time{}, fmt.Errorf("invalid date in %s: %q", file, value)
21		}
22	
23		for _, layout := range dateLayouts {
24			parsed, err := time.Parse(layout, value)
25			if err == nil {
26				return parsed.UTC(), nil
27			}
28		}
29	
30		return time.Time{}, fmt.Errorf("invalid date in %s: %q", file, value)
31	}
32	
33	// PageDate reads the date field from parsed front matter.
34	func PageDate(file string, fields map[string]string) (time.Time, error) {
35		raw := fields["date"]
36		return parseFrontMatterDate(file, raw)
37	}
